'use strict';
document.querySelectorAll('.password-toggle').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.getAttribute('aria-controls'));const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Ocultar':'Mostrar';button.setAttribute('aria-pressed',String(show));}));
async function api(endpoint,body){const response=await fetch(endpoint,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},credentials:'same-origin',body:body?JSON.stringify(body):undefined});let payload;try{payload=await response.json();}catch{throw new Error('Abra a Helpu pelo iniciador da pasta para utilizar sua conta.');}if(!response.ok){const error=new Error(payload.error||'Não foi possível concluir. Tente novamente.');error.status=response.status;throw error;}return payload;}
const authForm=document.querySelector('[data-auth]');
if(authForm){authForm.addEventListener('submit',async event=>{event.preventDefault();if(!authForm.reportValidity())return;const status=authForm.querySelector('.form-status');const submit=authForm.querySelector('[type=submit]');const previous=submit.innerHTML;status.hidden=true;submit.disabled=true;submit.textContent=authForm.dataset.auth==='signup'?'Criando sua conta…':'Entrando…';try{if(location.protocol==='file:')throw new Error('Para entrar ou criar uma conta, abra o arquivo INICIAR-HELPU.cmd na pasta do projeto.');const fields=Object.fromEntries(new FormData(authForm));await api('/api/auth/'+authForm.dataset.auth,fields);location.assign('portal.html');}catch(error){status.textContent=error.message==='Failed to fetch'?'Não foi possível conectar. Verifique se a Helpu está aberta e tente novamente.':error.message;status.hidden=false;submit.disabled=false;submit.innerHTML=previous;}});}
if(document.body.hasAttribute('data-account')){const status=document.querySelector('#account-status');api('/api/auth/me').then(({user})=>{document.querySelector('#account-name').textContent=user.name;document.querySelector('#account-email').textContent=user.email;document.querySelector('#account-company').textContent=user.company||'Não informada';status.hidden=true;document.querySelector('#account-content').hidden=false;document.querySelector('#logout').hidden=false;}).catch(error=>{if(error.status===401){location.replace('entrar.html');return;}status.textContent=error.message;});document.querySelector('#logout').addEventListener('click',async event=>{event.currentTarget.disabled=true;try{await api('/api/auth/logout',{});location.replace('entrar.html');}catch(error){status.textContent=error.message;status.hidden=false;event.currentTarget.disabled=false;}});}
